import csv, re, os
from pathlib import Path
from datetime import date, datetime, timedelta

base = Path('/app/logs')
ref = date(2025, 8, 12)
ranges = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (date(ref.year, ref.month, 1), ref),
}
severities = ['ERROR', 'WARNING', 'INFO']
counts = {period: {sev: 0 for sev in severities} for period in list(ranges.keys()) + ['total']}
pat = re.compile(r'\b(ERROR|WARNING|INFO)\b')
file_pat = re.compile(r'^(\d{4})-(\d{2})-(\d{2})_[^.]+\.log$')

for p in base.iterdir():
    if not p.is_file():
        continue
    m = file_pat.match(p.name)
    if not m:
        continue
    y, mo, d = map(int, m.groups())
    fdate = date(y, mo, d)
    text = p.read_text(errors='ignore')
    file_counts = {sev: 0 for sev in severities}
    for sev in pat.findall(text):
        file_counts[sev] += 1
    for sev in severities:
        counts['total'][sev] += file_counts[sev]
    for period, (start, end) in ranges.items():
        if start <= fdate <= end:
            for sev in severities:
                counts[period][sev] += file_counts[sev]

out = Path('/app/summary.csv')
rows = []
for period in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
    for sev in severities:
        rows.append([period, sev, counts[period][sev]])
with out.open('w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['period','severity','count'])
    w.writerows(rows)
print(out)
print('rows', len(rows)+1)
